namespace Schoolbox\Resource\Browser;

use Exception;

interface NodeInterface
{

    /* These constants do not relate 1:1 with instances of this interface. Rather this is the set of nodes types
     * that may be generated by instance of this interface.
     * eg, a MyFolder\Model node will decompose into 1 or more nodes (1 'folder' for itself, 0:N 'file' nodes for any MyFile\Model linked to it)
     * @see jquery.resourceTree.js
     */
    public const TYPE_ROOT      = 'root';
    public const TYPE_DEFAULT   = 'default';
    public const TYPE_FOLDER    = 'folder';
    public const TYPE_DIR       = 'dir';      // TODO deduplicate these - maybe - are they synonymous? (see PortfolioWebDAV)
    public const TYPE_COURSE    = 'course';
    public const TYPE_UNIT      = 'unit';
    public const TYPE_HOME      = 'home';
    public const TYPE_HOMEPAGE  = 'homepage'; // TODO deduplicate these
    public const TYPE_NO_ACCESS = 'noaccess';
    public const TYPE_FILE      = 'file';
    public const TYPE_LINK      = 'link';

    /**
     * Constructor
     *
     * $nodeId is the primary key of the category whose contents
     * you wish to present
     *
     * @param int    $nodeId
     * @param string $mimeFilter
     * @throws Exception
     */
    public function __construct($nodeId, $mimeFilter = null);


    /**
     * Render it out in a json format in case you need it
     */
    public function ajax();


    /**
     * Render it out so phplib can do it
     *
     * @return array
     */
    public function render();
}
